# Import essential libraries
import numpy as np

def load_file(file_path):
    """Load the number sequence from the file."""
    with open(file_path, 'r') as f:
        numbers = f.read().splitlines()
    return [int(num) for num in numbers]

def transform_to_matrix(data):
    """Attempt to transform numbers into a 2D matrix (for example, 29x29 or other dimensions QR code uses)."""
    # Example: Check if we can evenly fit into a perfect square shape
    for size in range(1, int(len(data)**0.5) + 1):
        if len(data) % size == 0:
            rows = size
            cols = len(data) // size
            return np.array(data).reshape(rows, cols)
    return None

